cssCode:
.parallax-wrap { height: 200vh; position: relative; width: 100%; }
.parallax-shape {
  position: absolute; top: 50%; left: 50%;
  width: 150px; height: 150px;
  background: radial-gradient(circle, #00f2fe, #4facfe);
  border-radius: 50%; filter: blur(10px);
  transform: translate(-50%, -50%);
  transition: transform 0.1s linear;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;position:relative;';

const wrap = document.createElement('div');
wrap.className = 'parallax-wrap';

const shape = document.createElement('div');
shape.className = 'parallax-shape';

wrap.appendChild(shape);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const scrolled = c.scrollTop;
  // Parallax speed effect
  shape.style.transform = `translate(-50%, calc(-50% + ${scrolled * 0.5}px))`;
});
